import {escapeHTML as esc} from './core.js';
const $=id=>document.getElementById(id),presets={counts:`MATCH (c:Commune {code: $code})<-[:INTERSECTS_DISPLAY]-(e:Element)
      -[:FROM_SOURCE]->(s:Source)-[:VARIANT_OF]->(l:Layer)
      -[:IN_GROUP]->(g:Group)-[:IN_THEME]->(t:Theme)
RETURN c.name AS commune, t.name AS theme, g.name AS groupe,
       l.display_name AS couche, s.status AS collecte,
       count(e) AS enregistrements
ORDER BY enregistrements DESC`,paths:`MATCH p=(c:Commune {code: $code})<-[:INTERSECTS_DISPLAY]-(:Element)
        -[:FROM_SOURCE]->(:Source)-[:VARIANT_OF]->(:Layer)
RETURN p LIMIT 100`,schema:`MATCH p=(l:Layer)-[:IN_GROUP]->(:Group)-[:IN_THEME]->(:Theme)
WHERE l.catalog_active = true
RETURN p LIMIT 100`};
let cities=[],last=null,health={connected:false};
function download(name,content,type='application/json'){const u=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function renderGraph(rows){const nodes=new Map(),edges=new Map();function visit(v){if(!v||typeof v!=='object')return;if(v.kind==='node')nodes.set(v.id,v);else if(v.kind==='relationship')edges.set(v.id,v);else Object.values(v).forEach(x=>Array.isArray(x)?x.forEach(visit):visit(x))}rows.forEach(visit);const root=$('graph');if(!nodes.size){root.innerHTML='<p class="micro" style="padding:20px">Cette requête renvoie des valeurs agrégées, pas des chemins. Utilisez « Relations des objets » pour voir les liens retournés.</p>';return}
 const shown=[...nodes.values()].slice(0,80),pos=new Map(shown.map((n,i)=>[n.id,{x:400+320*Math.cos(i*2*Math.PI/shown.length),y:210+170*Math.sin(i*2*Math.PI/shown.length)}]));
 root.innerHTML='<svg viewBox="0 0 800 420" role="img" aria-label="Relations réellement renvoyées par Neo4j"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#9ba99a"/></marker></defs>'+[...edges.values()].filter(e=>pos.has(e.start)&&pos.has(e.end)).map(e=>{const a=pos.get(e.start),b=pos.get(e.end);return `<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="#adbba6" stroke-width="1.2" marker-end="url(#arrow)"><title>${esc(e.type)}</title></line>`}).join('')+shown.map(n=>{const p=pos.get(n.id),name=n.properties.name||n.properties.display_name||n.properties.code||n.labels[0];return `<g><circle cx="${p.x}" cy="${p.y}" r="${n.labels.includes('Commune')?10:6}" fill="${n.labels.includes('Commune')?'#b78337':n.labels.includes('Element')?'#6c9b75':'#326b8c'}"><title>${esc(JSON.stringify(n.properties))}</title></circle><text x="${p.x+9}" y="${p.y+3}" font-size="8" fill="#173d31">${esc(String(name).slice(0,28))}</text></g>`}).join('')+'</svg>'+(nodes.size>80?'<p class="micro">80 nœuds affichés sur '+nodes.size+' reçus. Le JSON exporté conserve tous les résultats reçus.</p>':'');
}
async function check(){try{const r=await fetch('api/neo4j/health');health=await r.json()}catch{health={connected:false,reason:'Service Neo4j local indisponible.'}}$('connection').className='status'+(health.connected?'':' error');$('connection').textContent=health.connected?'Connecté à un véritable serveur Neo4j · '+(health.imported_cities?.length||0)+' communes importées':health.reason;$('run-query').disabled=!health.connected;$('import-city').disabled=!health.connected;cityStatus()}
function cityStatus(){const c=cities.find(c=>(c.name+' ('+c.code+')').toLowerCase()===$('city').value.toLowerCase()||c.name.toLowerCase()===$('city').value.toLowerCase());if(!c)return;const imported=health.imported_cities?.find(x=>x.code===c.code);$('city-status').textContent=imported?(imported.catalog_current?'Données importées le ':'Catalogue modifié : actualiser les données importées le ')+imported.imported_at:'Commune référencée ; ses objets doivent être importés avant interrogation.';try{const p=JSON.parse($('params').value);p.code=c.code;$('params').value=JSON.stringify(p,null,2)}catch{}}
$('cypher').value=presets.counts;$('preset').onchange=()=>$('cypher').value=presets[$('preset').value];$('city').oninput=cityStatus;
$('run-query').onclick=async()=>{const button=$('run-query');button.disabled=true;$('query-status').textContent='Requête exécutée par Neo4j…';try{const parameters=JSON.parse($('params').value);const r=await fetch('api/neo4j/query',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query:$('cypher').value,parameters,limit:500})});const data=await r.json();if(!r.ok)throw Error(data.detail||'Échec de requête');last=data;$('query-status').textContent=data.rows.length+' lignes reçues de Neo4j'+(data.truncated?' · Affichage limité à 500 lignes. Ajouter SKIP / LIMIT à la requête pour paginer.':'');$('results').innerHTML='<table><thead><tr>'+data.columns.map(c=>'<th>'+esc(c)+'</th>').join('')+'</tr></thead><tbody>'+data.rows.map(row=>'<tr>'+data.columns.map(k=>'<td>'+(row[k]&&typeof row[k]==='object'?'<details><summary>'+esc(row[k].kind||'Objet')+'</summary><pre>'+esc(JSON.stringify(row[k],null,2))+'</pre></details>':esc(String(row[k]??'—')))+'</td>').join('')+'</tr>').join('')+'</tbody></table>';renderGraph(data.rows);$('export-results').disabled=false}catch(e){$('query-status').textContent=e.message}finally{button.disabled=!health.connected}};
$('import-city').onclick=async()=>{try{const city=$('city').value.replace(/ \(\d+\)$/,'');const r=await fetch('api/neo4j/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({city})});const data=await r.json();if(!r.ok)throw Error(data.detail);$('import-city').disabled=true;const poll=async()=>{const job=await fetch('api/neo4j/jobs/'+data.id).then(r=>r.json());$('city-status').textContent='Import '+job.status+' · '+city;if(job.status==='running')setTimeout(poll,2000);else{$('city-status').textContent=job.status==='succeeded'?'Import Neo4j terminé.':job.log;await check()}};poll()}catch(e){$('city-status').textContent=e.message}};
$('download-query').onclick=()=>download('Renatura_requete.cypher',$('cypher').value+'\n// Paramètres : '+$('params').value,'text/plain');$('export-results').onclick=()=>download('Renatura_resultats_neo4j.json',JSON.stringify(last,null,2));
try{cities=await fetch('data/orientation/cities.json').then(r=>r.json());$('cities').innerHTML=cities.map(c=>'<option value="'+esc(c.name+' ('+c.code+')')+'">').join('')}catch{}
check();
